import{_ as a,o as t,c as p,a2 as r}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"需求价值的分析方法","description":"","frontmatter":{},"headers":[],"relativePath":"project/separate_need.md","filePath":"project/separate_need.md","lastUpdated":null}'),o={name:"project/separate_need.md"};function l(_,e,n,s,i,d){return t(),p("div",null,[...e[0]||(e[0]=[r('<h1 id="需求价值的分析方法" tabindex="-1">需求价值的分析方法 <a class="header-anchor" href="#需求价值的分析方法" aria-label="Permalink to &quot;需求价值的分析方法&quot;">​</a></h1><p>对需求的分析可以从用户、场景、需求、流程四个维度进行快速拆解。</p><ol><li><p>用户 用户是谁，有什么特性，用户画像具体是什么样的？如果对用户不了解还需要进一步做用户研究。</p></li><li><p>场景 用户在什么场景中有需求，场景可以是用户在什么时间和地点，会发生什么，如果不了解场景，最好到用户的使用场景中，当面去看用户怎么操作。</p></li><li><p>需求 用户的需求是无穷的，需求的背后一定是要结合用户具体的场景，脱离了场景的需求都是伪需求。</p></li><li><p>流程 流程决定了此需求和其它需求的关系，如何让用户最爽的满足一系列需求，就形成了流程，在B端是业务流程图，在C端是产品架构设计。</p></li></ol><p>我在日常的产品工作中，不大可能拿很多模型分析需求，论证需求，这样比较低效，公众号留言 需求画布，下载最新的需求画布模板。新手可以照着模板思考每个需求价值，老鸟时间长了表格可以扔掉，对每个需求心理默念即可。</p>',4)])])}const f=a(o,[["render",l]]);export{m as __pageData,f as default};
